class GenericPmCounter(GenericBts):
    """Counter keywords for eNB and gNB"""

    @login_logout
    def get_pm_interval(self, dist_name, abbr_group_name, bts_id=0, du_id=0):
        """
        Get the current parameter value for abbr
        :param dist_name: Destination name
        :param abbr_group_name: Abbreviation
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: value for abbr
        """
        dist_name = dist_name.format(self.get_bts_instance_id(bts_id, du_id))
        parameters = self._get_object_parameters_dict(dist_name=dist_name, bts_id=bts_id, du_id=du_id)
        logging.debug(parameters)
        pm_interval = parameters[abbr_group_name]
        return pm_interval

    @login_logout
    def set_pm_interval(self, dist_name, abbr_group_name, interval, bts_id=0, du_id=0):
        """
        Set PM interval
        :param dist_name: Destination name
        :param abbr_group_name: Abbreviation
        :param interval: Interval for PM counters
        :param bts_id: ID for BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        dist_name = dist_name.format(self.get_bts_instance_id(bts_id, du_id))
        self.admin.perform_parameter_recommissioning(dist_name=dist_name, parameter=abbr_group_name,
                                                     operation='update', value=interval, should_activate=True,
                                                     connection=self.rest_alias.format(bts_id, du_id),
                                                     skip_parameter_relation_errors=True)

    def wait_for_pm_measurements(self, interval, measurements, measurements_refresh_time=120):
        """
        Wait for several intervals PM counters
        :param interval: Interval for PM counters, e.g. "15min"
        :param measurements: Numbers of intervals, to wait one more intervals then specified
        :param measurements_refresh_time: Measurement refresh time
        :return: None
        """
        interval_minutes_value = self.__parse_minute(interval)
        interval_seconds_value = interval_minutes_value * 60
        self.wait_for_next_pm_period(interval=interval)
        for measurement in range(int(measurements) + 1):
            logging.debug('Waiting for PM interval of {} min to pass'.format(interval_minutes_value))
            time.sleep(interval_seconds_value)
        logging.debug('Waiting for refreshing the measurements')
        time.sleep(measurements_refresh_time)

    def validate_intervals_and_value_counter_ecpri_group(self, interval, measurements, bts_id=0, du_id=0):
        """
        Validate intervals and value counters for eCPRI
        :param interval: Interval for PM counters, e.g. "15min"
        :param measurements: Numbers of intervals
        :param bts_id: ID for BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        counters_ecpri = {
            'M40102C0': 16,
            'M40102C1': 8,
            'M40102C2': 16,
            'M40102C3': 16,
            'M40102C4': 1,
        }
        value_minute = self.__parse_minute(interval)
        value_second = value_minute * 60
        error_counters = {}
        for counter_id in counters_ecpri:
            error_id = self.__verify_counter(counter_id, counters_ecpri[counter_id], value_second, measurements,
                                             bts_id, du_id)
            if len(error_id) != 0:
                error_counters[counter_id] = error_id

        if len(error_counters) != 0:
            raise InvalidIntervalsOrValuesCounter('Errors: {}'.format(error_counters))

    def __verify_counter(self, counter_ids, value_per_second, value_second, measurements, bts_id=0, du_id=0):
        """
        Verify intervals and value counter
        :param counter_ids: Counter ID M...
        :param value_per_second: Expected value per second
        :param value_second: Duration of interval
        :param measurements: Numbers of intervals
        :param bts_id: ID for BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: Error messages
        """
        error_msg = []
        measurements = int(measurements)
        data_counter = self.get_counter(counter_ids, bts_id, du_id, wrap=True)

        for eth_distn, eth_counters in data_counter.items():
            raw_time_value = eth_counters['SBTS_NCPRI'][counter_ids]
            list_time = sorted(raw_time_value)
            secondary_link = False
            for measurement in range(1, measurements + 1):
                key_value = list_time[-measurements - 1]
                value = raw_time_value[key_value]
                interval_result = int(list_time[-measurement]) - int(list_time[-measurement - 1])
                target_value = value_per_second * value_second
                if interval_result != value_second:
                    error_msg.append('Bad interval counter {}, expected: {}, value: {} for ETHLK: {}'.format(
                        counter_ids, value_second, interval_result, eth_distn))
                elif not target_value - 10 <= value <= target_value + 10:
                    if value == 0 and (
                            counter_ids == 'M40102C2' or counter_ids == 'M40102C3') and secondary_link is False:
                        secondary_link = True
                        break
                    error_msg.append('Bad value counter {}, expected: {}, value {} for ETHLK {}'.format(
                        counter_ids, value_per_second * value_second, value, eth_distn))
        return error_msg

    @login_logout
    def get_counter(self, counter_ids, bts_id=0, du_id=0, timeout=180, wrap=False):
        """
        Get dict with data counter
        :param counter_ids: Counter IDs (splitted by comma)
        :param bts_id: ID for BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: procedure timeout in seconds
        :param wrap: If set to True, the hierarchy leading to the counter is flattened into a single string path. If False (default),
                      the path remains a nested dictionary structure.
                      without wrapp: {"MRBTS-1174": {"TNLSVC-1": {"TNL-2": {"ETHSVC-1": {"ETHLK-1": {"SBTS_NCPRI": {"M40102C0": "values ..."}}}}}}}
                      with wrapp: {"MRBTS-1174/TNLSVC-1/TNL-2/ETHSVC-1/ETHLK-1/SBTS_NCPRI": {"M40102C0": "values ..."}}
        :return: Data for counter
        """
        counter = self.admin.get_pm_counters(counter_ids=counter_ids,
                                             timeout=timeout,
                                             connection=self.rest_alias.format(bts_id, du_id),
                                             wrap_nidd=wrap)
        return counter

    @staticmethod
    def __parse_minute(interval):
        validate_variable = re.search(r'^\d+$', str(interval))
        if validate_variable is not None:
            return int(interval)
        return int(time_to_seconds(time=interval) / 60)

    @login_logout
    def get_pm_counters_file(self, local_path, bts_id=0, du_id=0):
        """
        Download PM file to the local directory if the PM files list is not empty
        :param local_path:      Path to save the file
        :type local_path:       str
        :param bts_id:          BTS id - related to Test Line configuration. Default: 0
        :type bts_id:           int
        :param du_id:           ID of Distribution Unit. Default: 0
        :type du_id:            int
        """

        self.admin.get_pm_files(local_file_path=local_path, timeout=120,
                                connection=self.rest_alias.format(bts_id, du_id))

    def wait_for_next_pm_period(self, interval="15min", delay=30):
        """
        Wait for the next counter cycle, indicated by the interval
        :param interval:                    Interval of the counter in minutes, e.g. "15min"
        :type  interval:                    str
        :param delay:                       Number of seconds to wait after the new period starts
        :type  delay:                       int
        :return: pm_period_start_time, pm_period_end_time
        """
        MolerTest.info("Wait for next measurement period")
        interval_minute_value = self.__parse_minute(interval)
        interval_seconds_value = interval_minute_value * 60
        waiting_time = interval_seconds_value - int(time.time()) % interval_seconds_value + delay
        logging.debug('Waiting for new PM period : {}'.format(timedelta(seconds=waiting_time)))
        time.sleep(waiting_time)

        current_timestamp = int(time.time())
        pm_period_start_time = current_timestamp - current_timestamp % 60
        pm_period_end_time = pm_period_start_time + interval_seconds_value

        return pm_period_start_time, pm_period_end_time

    @staticmethod
    def _validate_timestamps_number(extracted_data):
        for counter in extracted_data:
            for timestamps in counter['timestamps']:
                interval_list = list(timestamps.keys())
                if len(interval_list) < 2:
                    MolerTest.info("Not enough reports generated")
                    return False
        return True

    def _validate_counters_interval_value(self, expected_interval, extracted_data):
        for counter in extracted_data:
            for timestamps in counter['timestamps']:
                interval_list = list(timestamps.keys())
                interval_list.sort(reverse=True)
                actual_interval = int(interval_list[0]) - int(interval_list[1])
                if self.__parse_minute(expected_interval) == int(actual_interval / 60):
                    MolerTest.info("Proper interval value for counter {}".format(counter['counter_name']))
                else:
                    MolerTest.info("Counter {} does not have proper value of interval".format(counter['counter_name']))
                    return False
        return True

    def validate_counter_interval(self, counter_id, expected_interval, timeout='default', delay=30, bts_id=0, du_id=0):
        """
        Validate if interval value of specify PM counters.

        :param counter_id:               Counters ID M...
        :type  counter_id:               list or str (splitted by comma)
        :param expected_interval:        Expected interval in minutes, e.g. "15min"
        :type  expected_interval:        str
        :param timeout:                  timeout in minutes, e.g. "15min",
                                         if the value is 'default', it will be set to twice the expected interval
        :type  timeout:                  str
        :param delay:                    number of seconds to wait after the new period starts
        :type  delay:                    int
        :param bts_id:                   ID for BTS
        :type  bts_id:                   int
        :param du_id:                    DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type  du_id:                    int
        return:                          Last timestamp as int
        """
        if timeout == 'default':
            timeout = 2 * self.__parse_minute(expected_interval)

        waiting_time = 0
        incorrect_interval = True

        while incorrect_interval:
            if isinstance(counter_id, list):
                counter_id = ",".join(counter_id)
            counter_data = self.get_counter(counter_id)
            extracted_data = self.extract_counter_data_from_response(response=counter_data, counter_id=counter_id)
            if self._validate_timestamps_number(extracted_data):
                if self._validate_counters_interval_value(expected_interval, extracted_data):
                    MolerTest.info("All PM counters have proper interval value")
                    last_timestamp = int(sorted(extracted_data[0]['timestamps'][0].keys())[-1])
                    return last_timestamp
            if incorrect_interval:
                if waiting_time < self.__parse_minute(timeout):
                    self.wait_for_next_pm_period(interval=expected_interval, delay=delay)
                    waiting_time += self.__parse_minute(expected_interval)
                else:
                    MolerTest.error("PM counters interval have NOT change to correct value in last {} minute".format(
                        self.__parse_minute(timeout)), raise_exception=True)

    def validate_counter_is_inactive(self, counters, waiting_period="30min", delay=30, bts_id=0, du_id=0):
        """
        Validate that no new counter values were reported during the waiting period => last timestamp will be the same

        :param counters:       Counters ID M...
        :type  counters:       list
        :param waiting_period: how long the function should wait before fetching timestamps to compare against
                               in minutes, e.g. "15min"
        :type  waiting_period: str
        :param delay           Additional delay in seconds to wait before fetching timestamps after the wating period
        :type  delay           int
        :param bts_id:         ID for BTS
        :type  bts_id:         int
        :param du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type  du_id:          int
        """

        counter_ids = ",".join(counters)
        initial_counters_data = self.get_counter(counter_ids)
        MolerTest.sleep(self.__parse_minute(waiting_period) * 60 + delay)
        new_counters_data = self.get_counter(counter_ids)

        if initial_counters_data == new_counters_data:
            MolerTest.info("Counter data did not change after the waiting period of {} minutes".format(waiting_period))
        else:
            MolerTest.error("Counter data changed after the waiting period of {} minutes".format(waiting_period),
                            raise_exception=True)

    def extract_counter_data_from_response(self, response, counter_id):
        """
        Extract timestamp-value counter pairs from a GenericPmCounter.get_counter() response
        For the response structure is as follows (as far as I know and seen):

        BTS:
            /object_type/ - documented types are BTS, CELLS, CORE ELEMENT, SMOD:
                /unit/ - unit or its' component, different for most objects:
                    /counter group/ - grouping counters by category, can be nested:
                        ...
                        /counter_name/ - counter we are looking for:
                            /timestamp - value pairs/

        :param response:   Data returned by the GenericPmCounter.get_counter() function
        :type  response:   dict
        :param counter_id: Counters ID that should be extracted from the response
        :type  counter_id: list or str (splitted by comma)
        :return:           list of dict of counters with timestamp-value pairs

        Example:
        [
           {
              "counter_name":"M40018C0",
              "timestamps":[
                 {
                    "1662361200":23,
                    "1662362100":23,
                    "1662363720":23,
                    "1662363900":23
                 }
              ]
           },
           {
              "counter_name":"M40018C1",
              "timestamps":[
                 {
                    "1662361200":68,
                    "1662362100":68,
                    "1662363720":68,
                    "1662363900":68
                 }
              ]
           }
        ]
        """
        extracted_data = []
        if isinstance(counter_id, str):
            counter_id = counter_id.split(",")

        for counter in counter_id:
            data = self.__recursive_dict_search(dict_to_search=response, counter=counter, result=[])
            extracted_data.append({'counter_name': counter, 'timestamps': data})
        return extracted_data

    def __recursive_dict_search(self, dict_to_search, counter, result):
        keys = list(dict_to_search.keys())

        if counter in keys:
            return dict_to_search[counter]
        else:
            for key in keys:
                if isinstance(dict_to_search[key], dict):
                    values = self.__recursive_dict_search(dict_to_search[key], counter, result)
                    if isinstance(values, dict):
                        result.append(values)
        return result

    @load_moler_configuration_from_tl()
    def validate_pm_reports_generation_interval(self, expected_interval, bts_id=0):
        """
        Validate if interval of generating PM reports is set according to 'reportingIntervalPm' parameter value.

        :param expected_interval:             Expected interval in minutes, e.g. "15min"
        :type  expected_interval:             str
        :param bts_id: ID for BTS
        :type  bts_id:                        int
        :return:                              True/False
        """
        device_name = "GNB{}".format(bts_id)
        bts = DeviceFactory.get_device(device_name)
        bts.goto_state("FCT")
        cmd_ls_la = bts.get_cmd(cmd_name="ls", cmd_params={"path": "/tmp"})
        tmp_files = cmd_ls_la()
        reports_timestamps = []
        for filename in tmp_files["files"].keys():
            if "PM.BTS" in filename and "ANY.xml.gz" in filename:
                sec = datetime.strptime(filename.split(".")[2] + filename.split(".")[3], '%Y%m%d%H%M%S') - datetime(
                    1900, 1, 1)
                reports_timestamps.append(int(sec.total_seconds() / 60))
        if len(reports_timestamps) > 2:
            reports_timestamps.sort(reverse=True)
            actual_interval = reports_timestamps[0] - reports_timestamps[1]
            if self.__parse_minute(expected_interval) == actual_interval:
                MolerTest.info("Reporting interval PM is set correctly")
                return True
            else:
                MolerTest.info(
                    "Expected value of reporting interval PM is {} min but reports are generated with {} min "
                    "interval".format(expected_interval, actual_interval))
                return False
        else:
            return False

    def wait_for_pm_reports_generation_interval_change(self, expected_interval, timeout):
        """
        Wait for interval of generating PM reports change according to 'reportingIntervalPm' parameter value.

        :param expected_interval:             Expected interval in minutes, e.g. "15min"
        :type  expected_interval:             str
        :param timeout:                       timeout in minutes, e.g. "15min"
        :type  timeout:                       str
        :return:                              True/False
        """
        waiting_time = 0
        incorrect_interval = True
        while incorrect_interval:
            MolerTest.sleep(300)
            if self.validate_pm_reports_generation_interval(expected_interval):
                incorrect_interval = False
                MolerTest.info("Interval of generating PM reports has changed to correct value in {} minutes".format(
                    waiting_time))
            else:
                waiting_time += 5
            if waiting_time > self.__parse_minute(timeout):
                incorrect_interval = False
                MolerTest.error(
                    "Interval of generating PM reports have NOT change to correct value in last {} minute".format(
                        timeout), raise_exception=True)

    @login_logout_GUI
    def get_pm_counter_info_via_gui(self, counter_id, bts_id=0, du_id=0, only_latest_value=True):
        """
        Function to fetch a counter value from BTS Counters section in WebEM via Selenium

        :param counter_id: counter name to fetch from GUI
        :type  counter_id: str
        :param bts_id:     ID for BTS
        :type  bts_id:     int
        :param du_id:      DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type  du_id:      int
        """
        result = self.gui_coam.get_bts_counters_info(counter_id=counter_id,
                                                     sbts=self.gui_alias.format(bts_id, du_id))

        return next(iter(result.values())) if only_latest_value else result

    def get_simplified_cell_pm_counters_result(self, counter_list, bts_id=0, du_id=0):
        """
        Get simplified cell PM counters result. It works only for counters available per cell.
        :param counter_list: List of counter IDs
        :param bts_id: ID for BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: Simplified cell PM counters result e.g.
        {
            "NRCELL-411": [
                {
                    "counter_name": "M55118C02005",
                    "timestamps": [
                        {
                            "1717578300": 0,
                            "1717578600": 0,
                            "1717578900": 1,
                            "1717579200": 0
                        }
                    ]
                },
                {
                    "counter_name": "M55118C03005",
                    "timestamps": [
                        {
                            "1717578300": 0,
                            "1717578600": 0,
                            "1717578900": 1,
                            "1717579200": 0
                        }
                    ]
                }
            ],
            "NRCELL-412": [
                {
                    "counter_name": "M55118C02005",
                    "timestamps": [
                        {
                            "1717578300": 0,
                            "1717578600": 0,
                            "1717578900": 0,
                            "1717579200": 0
                        }
                    ]
                },
                {
                    "counter_name": "M55118C03005",
                    "timestamps": [
                        {
                            "1717578300": 0,
                            "1717578600": 0,
                            "1717578900": 0,
                            "1717579200": 0
                        }
                    ]
                }
            ]
        }
        """
        counter_ids_string = ','.join(counter_list)
        counter_result = self.get_counter(counter_ids=counter_ids_string, bts_id=bts_id, du_id=du_id)
        cell_counters = PmCounterOutputGetter(pm_counter_output=counter_result).get_cells_counters(bts_id=bts_id,
                                                                                                   du_id=du_id)

        simplified_result = {}
        for cell_id in cell_counters:
            simplified_result[cell_id] = self.extract_counter_data_from_response(
                response=cell_counters[cell_id],
                counter_id=counter_ids_string)
        logging.debug("Simplified pm counters result: {}".format(simplified_result))
        return simplified_result


