class PmCounterOutputGetter(object):
    def __init__(self, pm_counter_output=None, bts_type='GNB'):
        self.pm_counter_output = pm_counter_output
        self.bts_type = bts_type

    def get_cells_counters(self, pm_counter_output=None, cell_type='NR', bts_id=0, du_id=0):
        """
        Get the counters for all cells.
        Get proper output - handling changes made in CB009480.
                            pm_counter_output['BTS']['CELLS'] --> pm_counter_output['BTS'][<mrbts>][<nrbts>]

        :param dict pm_counter_output: The PM counter output dictionary.
                                       If not provided, the instance's `pm_counter_output` will be used.
        :param str cell_type: The cell type of the given RAT. Default is 'NR' Possible values ['NR', 'LTE'].
        :param int bts_id: The BTS ID related to the Test Line configuration. Default is 0.
        :param int du_id: The DU ID (Distributed Unit) related to the Test Line configuration. Default is 0.
        :return: The counters for all cells.
        :rtype: dict
        """

        pm_counter_output = pm_counter_output if pm_counter_output else self.pm_counter_output
        bts_dist_name = self._get_bts_dist_name(bts_id=bts_id, du_id=du_id, cell_type=cell_type)
        bts_instance_name, global_bts_name = bts_dist_name.split('/')
        if 'CELLS' in pm_counter_output['BTS']:
            return pm_counter_output['BTS']['CELLS']
        return pm_counter_output['BTS'][bts_instance_name][global_bts_name]

    def get_cell_counters(self, cell_id, cell_type='NR', pm_counter_output=None, bts_id=0, du_id=0):
        """
        Get the counters for a specific cell.
        Get proper output - handling changes made in CB009480.
                            pm_counter_output['BTS']['CELLS'] --> pm_counter_output['BTS'][<mrbts>][<nrbts>]

        :param str cell_id: The cell ID.
        :param dict pm_counter_output: The PM counter output dictionary.
                                       If not provided, the instance's `pm_counter_output` will be used.
        :param str cell_type: The cell type of the given RAT. Default is 'NR' Possible values ['NR', 'LTE'].
        :param int bts_id: The BTS ID related to the Test Line configuration. Default is 0.
        :param int du_id: The DU ID (Distributed Unit) related to the Test Line configuration. Default is 0.
        :return: The counters for the specific cell.
        :rtype: dict
        """

        pm_counter_output = pm_counter_output if pm_counter_output else self.pm_counter_output
        cell_dist_name = self._get_cell_dist_name(bts_id=bts_id, du_id=du_id, cell_type=cell_type, cell_id=cell_id)
        bts_instance_name, global_bts_name, cell_name = cell_dist_name.split('/')
        if 'CELLS' in pm_counter_output['BTS']:
            return pm_counter_output['BTS']['CELLS'][cell_name]
        return pm_counter_output['BTS'][bts_instance_name][global_bts_name][cell_name]

    def get_bts_counters(self, pm_counter_output=None):
        """
        Get the counters for the BTS.
        Get proper output - handling changes made in CB009480.
                            pm_counter_output['BTS']['BTS'] --> pm_counter_output['BTS']

        :param dict pm_counter_output: The PM counter output dictionary.
                                       If not provided, the instance's `pm_counter_output` will be used.
        :return: The counters for the BTS.
        :rtype: dict
         """

        if pm_counter_output is None:
            pm_counter_output = self.pm_counter_output

        if 'BTS' in pm_counter_output['BTS']:
            return pm_counter_output['BTS']['BTS']
        return pm_counter_output['BTS']

    def _get_bts_dist_name(self, bts_id=0, du_id=0, cell_type='NR'):
        bts_instance_id, global_bts_id, pattern_class = self._get_basic_params(
            bts_id=bts_id, du_id=du_id, cell_type=cell_type)
        bts_dist_name = pattern_class.bts_dist_name.format(bts_instance_id, global_bts_id)
        return bts_dist_name

    def _get_cell_dist_name(self, cell_id, cell_type='NR', bts_id=0, du_id=0):
        bts_instance_id, global_bts_id, pattern_class = self._get_basic_params(
            bts_id=bts_id, du_id=du_id, cell_type=cell_type)
        cell_dist_name = pattern_class.cell_dist_name.format(bts_instance_id, global_bts_id, cell_id)
        return cell_dist_name

    def _get_basic_params(self, bts_id=0, du_id=0, cell_type='NR'):
        bts_instance_id = tl_config.get_bts_instance_id(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        global_bts_id = tl_config.get_bts_instance_id(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        pattern_class = GnbDistNamePatterns if cell_type.upper() == 'NR' else EnbDistNamePatterns
        return bts_instance_id, global_bts_id, pattern_class


class ComparePmCounters(object):
    """
    A set of keywords helping to compare the measurement results of PM counters
    Simplify sample usage:

    -------------------------------------EXAMPLE---------------------------------------------------
    *** Variables ***
    @{COUNTERS}    M55118C04005  M55118C05005

    *** Test Cases ***
    Sample Test Case
        gnbcounter.Wait for Next PM Period    interval=5min    delay=${120}
        ${result1}          gnbcounter.Get Simplified Cell PM counters Result  counter_list=${COUNTERS}

        # Test Body

        gnbcounter.Wait for Next PM Period    interval=5min    delay=${120}
        ${result2}          gnbcounter.Get Simplified Cell PM counters Result  counter_list=${COUNTERS}
        ${calculated_diff}  Calculate PM Counter Diff  ${result1}  ${result2}
        Verify PM Counter Diff   ${calculated_diff}  <counter_ids_to_check>  <cell_ids_to_check>  expected_diff=${1}
    -------------------------------------END--------------------------------------------------------

    Get Simplified Cell PM counters Result and Verify PM Counter Diff Keywords are general.
    To increase readability please consider creating dedicated KWs  for your test case(using the above KW in the body)
    """
    @staticmethod
    def calculate_pm_counter_diff(simplified_result1, simplified_result2):
        """
        Calculate difference between sum of counter values for each cell and counter.
        (simplified_result2 - simplified_result1)
        :param simplified_result1: Simplified cell PM counters result
                                   (returned from get_simplified_cell_pm_counters_result)
        :param simplified_result2: Simplified cell PM counters result
                                   (returned from get_simplified_cell_pm_counters_result)
        :return: dict with differences between sum of counter values for each cell and counter
                {
                    "NRCELL-411": {
                        "M55118C04005": {
                            "diff": 56,
                            "interval_numbers": 1
                        },
                        "M55118C05005": {
                            "diff": 0,
                            "interval_numbers": 1
                        },
                        "M55316C02001": {
                            "diff": 56,
                            "interval_numbers": 1
                    },
                    "NRCELL-412": {
                        "M55118C04005": {
                            "diff": 0,
                            "interval_numbers": 1
                        },
                        "M55118C05005": {
                            "diff": 56,
                            "interval_numbers": 1
                        },
                        "M55316C02001": {
                            "diff": 55,
                            "interval_numbers": 1
                        },
                        }
                    }
                }
        """
        sum1_per_cell = ComparePmCounters._calculate_sum(simplified_result1)
        sum2_per_cell = ComparePmCounters._calculate_sum(simplified_result2)
        diff = {}
        for cell_id in sum2_per_cell:
            diff[cell_id] = {}
            for counter_name in sum2_per_cell[cell_id]:
                sum1_counter = sum1_per_cell[cell_id][counter_name]
                sum2_counter = sum2_per_cell[cell_id][counter_name]

                diff[cell_id][counter_name] = {
                    'diff': sum2_counter['sum'] - sum1_counter['sum'],
                    'interval_numbers': sum2_counter['interval_numbers'] - sum1_counter['interval_numbers']
                }
        logging.debug("Calculated diff between sum of counter values: {}".format(diff))
        return diff

    @staticmethod
    def check_pm_counter_diff(counter_diff_dict, counter_ids_to_check, cell_ids_to_check, expected_diff, tolerance=0):
        """
        Check if the difference between sum of counter values is as expected.
        :param counter_diff_dict: Dictionary with counter differences. results of 'calculate_pm_counter_diff'
        :param counter_ids_to_check: List of counter IDs to check. Counter_diff_dict could contain more counters
        :param cell_ids_to_check: List of cell IDs to check. Counter_diff_dict could contain more cells
        :param expected_diff: Expected difference between sum of counter values
        :param tolerance: Tolerance for expected difference
        :return: True if the difference between sum of counter values is as expected, False otherwise
        """

        def check_counter_record(counter_record, expected_diff, tolerance):
            diff = counter_record['diff']
            interval_numbers = counter_record['interval_numbers']
            msg_template = f"Expected Diff: {expected_diff}, Diff: {diff}, interval numbers: {interval_numbers}"
            if abs(diff - expected_diff) <= tolerance and interval_numbers > 0:
                logging.debug("Verification PASSED " + msg_template)
                return True
            else:
                logging.error("Verification FAILED " + msg_template)
                return False

        logging.debug("Checking counter diff for \n\tcounter_ids: {}"
                      "\n\tcell_ids_to_check: {}"
                      "\n\texpected_diff: {}"
                      "\n\ttolerance: {}".format(counter_ids_to_check, cell_ids_to_check,
                                                 expected_diff, tolerance))

        expected_all_status_len = len(counter_ids_to_check) * len(cell_ids_to_check)
        found_cells = [cell_id for cell_id in counter_diff_dict if cell_id in cell_ids_to_check]
        all_statuses = [check_counter_record(counter_diff_dict[cell_id][counter_name], expected_diff, tolerance)
                        for cell_id in found_cells
                        for counter_name in counter_diff_dict[cell_id]
                        if counter_name in counter_ids_to_check]

        if set(cell_ids_to_check) != set(found_cells):
            logging.debug("Expected cells to check: {}, found cells: {}".format(cell_ids_to_check, found_cells))
            logging.debug("Please check definition of variables.py file")
            return False

        if all_statuses and all(all_statuses) and len(all_statuses) == expected_all_status_len:
            return True

        return False

    @staticmethod
    def verify_pm_counter_diff(counter_diff_dict, counter_ids_to_check, cell_ids_to_check, expected_diff, tolerance=0):
        """
        Base function to verify the difference between sum of counter values. Please use it to build your own
        verification KW
        """
        if not ComparePmCounters.check_pm_counter_diff(counter_diff_dict, counter_ids_to_check,
                                                       cell_ids_to_check, expected_diff, tolerance):
            raise CounterVerificationFailed("Verification FAILED - please check logs for details")

    @staticmethod
    def _calculate_sum(simplified_result):
        result = {}
        for cell_id in simplified_result:
            result[cell_id] = {}
            for record in simplified_result[cell_id]:
                sum_of_values = 0
                for timestamp in record['timestamps'][0]:
                    sum_of_values += record['timestamps'][0][timestamp]
                result[cell_id][record['counter_name']] = {
                    'sum': sum_of_values,
                    'interval_numbers': len(record['timestamps'][0])
                }
        return result
